cat power_mod(cat a, cat e, cat mod) {
	if(e <= 0) return 1;
	cat x = power_mod(a, e/2, mod);
	x = x * x % mod;
	return (e & 1) ? x * a % mod : x;
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	cout << fixed << setprecision(10);
	int N, M;
	cat mod;
	cin >> N >> M >> mod;
	vector<cat> factorials(N+1, 1), inv_factorials(N+1, 1);
	for(int i = 1; i <= N; i++) {
		factorials[i] = factorials[i-1] * i % mod;
		inv_factorials[i] = inv_factorials[i-1] * power_mod(i, mod-2, mod) % mod;
	}
	vector<cat> count_arr(M+1, 0);
	vector<cat> sum_arr(M+1, 0);
	count_arr[0] = 1;
	for(int m = 1; m <= M; m++) {
		for(int k = 0; k < m; k++) {
			cat left_c = count_arr[k] * inv_factorials[k] % mod;
			cat right_c = count_arr[m-1-k] * inv_factorials[m-1-k] % mod;
			cat left_s = sum_arr[k] * inv_factorials[k] % mod;
			cat right_s = sum_arr[m-1-k] * inv_factorials[m-1-k] % mod;
			count_arr[m] += left_c * right_c % mod * (m+1);
			sum_arr[m] += (left_s * right_s + left_c * right_s + left_s * right_c) % mod * (m+1);
			sum_arr[m] += left_c * right_c % mod * (k*(k+1)+(m-k)*(m-k-1))/2 % mod;
		}
		count_arr[m] = count_arr[m] % mod * factorials[m-1] % mod;
		sum_arr[m] = sum_arr[m] % mod * factorials[m-1] % mod;
	}
	vector<vector<cat>> cnt_ans(N+1, vector<cat>(M+1, 0));
	vector<vector<cat>> sum_ans(N+1, vector<cat>(M+1, 0));
	cnt_ans[0][0] = 1;
	for(int i = 1; i <= N; i++) {
		for(int j = 0; j <= min(i, M); j++) {
			cnt_ans[i][j] = cnt_ans[i-1][j];
			sum_ans[i][j] = sum_ans[i-1][j];
			if(j == i) {
				cnt_ans[i][j] += count_arr[i] * inv_factorials[i] % mod;
				sum_ans[i][j] += sum_arr[i] * inv_factorials[i] % mod;
			}
			for(int k = 1; k <= min(j, i-1); k++) {
				cat c = count_arr[k] * inv_factorials[k] % mod;
				cat s = sum_arr[k] * inv_factorials[k] % mod;
				cnt_ans[i][j] += cnt_ans[i-1-k][j-k] * c % mod;
				sum_ans[i][j] += (sum_ans[i-1-k][j-k] * c + cnt_ans[i-1-k][j-k] * s) % mod;
			}
			cnt_ans[i][j] %= mod;
			sum_ans[i][j] %= mod;
		}
	}
	cat final_result = sum_ans[N][M] * factorials[M] % mod;
	cout << final_result << "\n";
}
